head.b:skin:
  /* Theme: Daydreams Massage Jakarta - Blogger Edition (MIT License) */
  :root {
    --bg-dark: #0a0a0a;
    --bg-surface: #141414;
    --bg-card: #1c1c1c;
    --border-subtle: #262626;
    --gold-primary: #d4af37;
    --gold-light: #fef08a;
    --gold-gradient: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
    --text-primary: #f5f5f5;
    --text-muted: #a3a3a3;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    background: var(--bg-dark);
    color: var(--text-primary);
    font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
    line-height: 1.6;
    overflow-x: hidden;
  }

  h1, h2, h3, .font-serif {
    font-family: 'Playfair Display', Georgia, serif;
  }

  a { color: var(--gold-primary); text-decoration: none; }
  a:hover { text-decoration: underline; }

  .container { max-width: 1200px; margin: 0 auto; padding: 0 20px; }
  .btn-gold {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    background: var(--gold-gradient);
    color: #0a0a0a;
    font-weight: 700;
    font-size: 14px;
    border-radius: 9999px;
    padding: 12px 28px;
    text-decoration: none;
    border: none;
    cursor: pointer;
    box-shadow: 0 10px 20px rgba(217, 119, 6, 0.2);
    transition: transform 0.2s, box-shadow 0.2s;
  }
  .btn-gold:hover {
    transform: translateY(-2px);
    box-shadow: 0 14px 28px rgba(217, 119, 6, 0.35);
    text-decoration: none;
  }

  /* PWA Banner Styles */
  #pwa-install-banner-blogger {
    display: none;
    position: fixed;
    top: 10px;
    left: 10px;
    right: 10px;
    max-width: 600px;
    margin: 0 auto;
    background: rgba(20, 20, 20, 0.96);
    border: 1px solid rgba(245, 158, 11, 0.4);
    border-radius: 16px;
    padding: 14px 18px;
    z-index: 99999;
    box-shadow: 0 20px 40px rgba(0,0,0,0.8);
    backdrop-filter: blur(10px);
  }

  /* Cookie Banner Styles */
  #cookie-consent-blogger {
    display: none;
    position: fixed;
    bottom: 20px;
    left: 20px;
    right: 20px;
    max-width: 440px;
    background: rgba(20, 20, 20, 0.96);
    border: 1px solid #333;
    border-radius: 16px;
    padding: 18px;
    z-index: 99998;
    box-shadow: 0 20px 40px rgba(0,0,0,0.8);
    backdrop-filter: blur(10px);
  }

  /* Tag Pencarian Google Cloud */
  .tag-cloud {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 14px;
  }
  .tag-item {
    background: #1f1f1f;
    border: 1px solid #333;
    color: #d4d4d4;
    padding: 6px 14px;
    border-radius: 10px;
    font-size: 12px;
    text-decoration: none;
    transition: all 0.2s;
  }
  .tag-item:hover {
    border-color: #f59e0b;
    color: #f59e0b;
    text-decoration: none;
    transform: translateY(-1px);
  }

body.script:
  //
  // 1. Service Worker Registration
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', function() {
      navigator.serviceWorker.register('/sw.js').then(function(reg) {
        console.log('PWA ServiceWorker registered with scope:', reg.scope);
      }).catch(function(err) {
        console.log('PWA ServiceWorker registration failed:', err);
      });
    });
  }

  // 2. PWA Before Install Prompt Handler
  var deferredPWAPrompt = null;
  var isIOS = /iphone|ipad|ipod/.test(window.navigator.userAgent.toLowerCase());
  var isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;

  window.addEventListener('beforeinstallprompt', function(e) {
    e.preventDefault();
    deferredPWAPrompt = e;
    if (!isStandalone && !sessionStorage.getItem('daydreams_pwa_dismissed')) {
      var banner = document.getElementById('pwa-install-banner-blogger');
      if (banner) banner.style.display = 'block';
      var headerBtn = document.getElementById('btn-pwa-header');
      if (headerBtn) headerBtn.style.display = 'inline-block';
    }
  });

  // If iOS Safari, also show prompt option
  window.addEventListener('load', function() {
    if (isIOS && !isStandalone && !sessionStorage.getItem('daydreams_pwa_dismissed')) {
      var banner = document.getElementById('pwa-install-banner-blogger');
      if (banner) banner.style.display = 'block';
      var headerBtn = document.getElementById('btn-pwa-header');
      if (headerBtn) headerBtn.style.display = 'inline-block';
      var actionBtn = document.getElementById('btn-pwa-action');
      if (actionBtn) actionBtn.innerText = 'Cara Pasang di iPhone';
    }
  });

  function triggerPWAInstall() {
    if (deferredPWAPrompt) {
      deferredPWAPrompt.prompt();
      deferredPWAPrompt.userChoice.then(function(choice) {
        if (choice.outcome === 'accepted') {
          dismissPWABanner();
        }
        deferredPWAPrompt = null;
      });
    } else if (isIOS) {
      var modal = document.getElementById('ios-pwa-modal');
      if (modal) modal.style.display = 'flex';
    } else {
      alert('Untuk memasang aplikasi ini di browser Anda: klik tombol Titik Tiga (⋮) atau ikon Pasang di bilah alamat browser, lalu pilih "Instal Daydreams Massage".');
    }
  }

  function dismissPWABanner() {
    var banner = document.getElementById('pwa-install-banner-blogger');
    if (banner) banner.style.display = 'none';
    sessionStorage.setItem('daydreams_pwa_dismissed', 'true');
  }

  // 3. Cookie Consent Handler
  window.addEventListener('load', function() {
    var cookieConsent = localStorage.getItem('daydreams_cookie_consent');
    if (!cookieConsent) {
      setTimeout(function() {
        var cBox = document.getElementById('cookie-consent-blogger');
        if (cBox) cBox.style.display = 'block';
      }, 1200);
    }
  });

  function acceptBloggerCookie() {
    localStorage.setItem('daydreams_cookie_consent', 'all');
    var cBox = document.getElementById('cookie-consent-blogger');
    if (cBox) cBox.style.display = 'none';
  }

  function dismissBloggerCookie() {
    localStorage.setItem('daydreams_cookie_consent', 'essential');
    var cBox = document.getElementById('cookie-consent-blogger');
    if (cBox) cBox.style.display = 'none';
  }

  function showBloggerCookieSettings() {
    var cBox = document.getElementById('cookie-consent-blogger');
    if (cBox) cBox.style.display = 'block';
  }
  //
